import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`executive-coach-audit`,heroTitle:`Audit your executive coach in minutes`,heroSubtitle:`Perplexity Computer reviews an executive coach site, credibility signals, offers, and client proof so you can decide who is worth a call.`,inputUrlCta:`Audit this coach`,inputUrlPlaceholder:`coachwebsite.com`,inputUrlPrefill:`Go to {url} and audit this executive coach. 1) Review the coach website for positioning, executive audience fit, services, case studies, credentials, testimonials, and booking flow. 2) Analyze public reviews, social profiles, thought leadership, and client proof where available. 3) Benchmark against other executive coaches serving similar leaders. 4) Identify strengths, risks, missing proof, pricing or offer ambiguity, and questions to ask before booking. 5) Deliver a clear recommendation with a scorecard and outreach questions.`,heroOverlaySteps:[`Reviewing positioning, services, proof, credentials, and booking flow`,`Checking public signals, testimonials, and thought leadership quality`,`Benchmarking against comparable executive coaches and advisory offers`,`Scorecard, risks, and questions to ask before booking ready to use`],generatingSteps:[`Visiting {url} to review the coach site, offers, credentials, and booking path`,`Designing an agent to analyze testimonials, public signals, and thought leadership`,`Configuring competitive benchmarking and executive-coach scorecard criteria`,`Setting up a recommendation report with risks and discovery-call questions`],featureSectionTitle:`From coaching site to confident shortlist`,featureCardTitles:[`Connects your research signals`,`Questions you can ask now`],featureCardDescriptions:[`Computer breaks coach evaluation into site review, proof analysis, market benchmarking, and risk assessment.`,`Websites, LinkedIn, Google results, reviews, and notes can all feed one workflow so your shortlist stays grounded.`,`Coach scorecards. Proof gaps. Comparable positioning. Discovery-call questions. Computer gives you a faster way to evaluate fit.`],capabilitySectionTitle:`Your coach diligence team, on demand`,capabilitySectionSubtitle:`Paste a coach website and get back a structured audit before you book a call.`,capabilityCards:[{title:`Coach Positioning Review`,description:`Computer can evaluate the coach website for audience fit, services, offer clarity, testimonials, case studies, and booking friction.`},{title:`Credibility Signal Check`,description:`Computer can analyze credentials, public profiles, thought leadership, and client proof to separate substance from vague claims.`},{title:`Comparable Benchmarking`,description:`Computer can compare the coach against similar executive coaching offers so pricing, proof, and specialization are easier to judge.`},{title:`Connect Your Notes`,description:`Computer can organize findings across Docs, Sheets, Notion, and your candidate shortlist.`},{title:`Remember Your Criteria`,description:`Computer can remember your leadership goals, coaching preferences, and deal breakers so future audits start from your rubric.`},{title:`Follow-Up Tracking`,description:`Computer can track open questions after discovery calls and update the coach scorecard as new information arrives.`}]});export{t as default};
